    digits = sorted(set(''.join(map(str, args))))
    return digits

def generate_permutations(base_list, limit):
    total_sum = 0
    for r in range(1, limit + 1):
        for perm in permutations(base_list, r):
            total_sum += sum(perm)
    return total_sum

def calculate_sums(permutations):
    return sum((sum(map(int, perm)) for perm in permutations))

def gta(limit, *args):
    base_list = sorted(set((digit for number in args for digit in str(number))))
    total_sum = 0
    for r in range(1, limit + 1):
        for perm in permutations(base_list, r):
            total_sum += sum((int(digit) for digit in perm))
    return total_sum

