from __future__ import annotations

def count_frequencies(s: str) -> dict:
    frequency = {}
    for char in s:
        if char.islower():
            frequency[char] = frequency.get(char, 0) + 1
    return frequency

def filter_frequencies(freqs: dict) -> dict:
    return {letter: count for letter, count in freqs.items() if count > 1}

def format_result(freqs: dict) -> str:
    result = []
    for letter, (max_freq, s1_freq, s2_freq) in sorted(freqs.items(), key=lambda x: (-len(x[1][0]), x[0])):
        if max_freq > 1:
            prefix = '=:'
            if s1_freq > 0:
                prefix = '1:'
            elif s2_freq > 0:
                prefix = '2:'
            result.append(f'{prefix}{letter * max_freq}')
    return '/'.join(result)

def mix(s1: str, s2: str) -> str:
    from collections import Counter
    counter1 = Counter((c for c in s1 if c.islower()))
    counter2 = Counter((c for c in s2 if c.islower()))
    max_freqs = {}
    for letter in set(counter1) | set(counter2):
        max_freqs[letter] = max(counter1.get(letter, 0), counter2.get(letter, 0))
    filtered_freqs = {letter: freq for letter, freq in max_freqs.items() if freq > 1}
    result = format_result(filtered_freqs)
    return result

