def count_frequencies(s: str) -> dict:
    frequency = {}
    for char in s:
        if char.islower():
            frequency[char] = frequency.get(char, 0) + 1
    return frequency

def filter_frequencies(freqs: dict) -> dict:
    return {letter: count for letter, count in freqs.items() if count > 1}

def format_output(freqs: dict) -> str:
    filtered_freqs = filter_frequencies(freqs)
    result = []
    for letter, (max_count, sources) in sorted(filtered_freqs.items(), key=lambda x: (-len(x[1][0]), x[0])):
        if len(sources) == 1:
            result.append(f'{sources[0]}:{letter * max_count}')
