def mix(s1: str, s2: str) -> str:
    from collections import Counter
    freq1 = Counter((c for c in s1 if c.islower()))
    freq2 = Counter((c for c in s2 if c.islower()))
    max_freq = {}
    for c in set(freq1) | set(freq2):
        max_freq[c] = max(freq1.get(c, 0), freq2.get(c, 0))
    filtered_freqs = {c: freq for c, freq in max_freq.items() if freq > 1}
    output = []
    for c, freq in sorted(filtered_freqs.items(), key=lambda x: (-len(x[1]), x[0])):
        if freq1[c] == freq2[c]:
            output.append(f'=:{freq * c}')
        elif freq1[c] > freq2[c]:
            output.append(f'1:{freq * c}')
        else:
            output.append(f'2:{freq * c}')
    return format_output(output)

