def is_perfect_square(x):
    if x < 0:
        return False
    root = int(x ** 0.5)
    return root * root == x

def generate_squares(limit):
    squares = []
    i = 1
    while i * i <= limit:
        squares.append(i * i)
        i += 1
    return squares

def find_min_squares(n, squares):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for square in squares:
        for i in range(square, n + 1):
            dp[i] = min(dp[i], dp[i - square] + 1)
    return dp[n]

def sum_of_squares(n):
    squares = [i * i for i in range(1, int(n ** 0.5) + 1)]
    return find_min_squares(n, squares)

