def format_range(start, end):
    if end - start < 2:
        return str(start)
    return f'{start}-{end}'

def process_sequence(numbers):
    if not numbers:
        return ''
    result = []
    start = numbers[0]
    end = numbers[0]
    for num in numbers[1:]:
        if num == end + 1:
            end = num
        else:
            if end == start:
                result.append(str(start))
            else:
                result.append(f'{start}-{end}')
            start = num
            end = num
    if end == start:
        result.append(str(start))
    else:
        result.append(f'{start}-{end}')
    return ','.join(result)

def solution(args):
    return process_sequence(args)

