from __future__ import annotations

def seconds_to_units(seconds):
    if seconds == 0:
        return 'now'
    units = []
    years = seconds // (365 * 24 * 3600)
    if years > 0:
        units.append(f"{years} year{('s' if years > 1 else '')}")
        seconds %= 365 * 24 * 3600
    days = seconds // (24 * 3600)
    if days > 0:
        units.append(f"{days} day{('s' if days > 1 else '')}")
        seconds %= 24 * 3600
    hours = seconds // 3600
    if hours > 0:
        units.append(f"{hours} hour{('s' if hours > 1 else '')}")
        seconds %= 3600
    minutes = seconds // 60
    if minutes > 0:
        units.append(f"{minutes} minute{('s' if minutes > 1 else '')}")
        seconds %= 60
    if seconds > 0:
        units.append(f"{seconds} second{('s' if seconds > 1 else '')}")
    if len(units) > 1:
        return ', '.join(units[:-1]) + ' and ' + units[-1]
    else:
        return units[0]

def format_components(components):
    formatted_parts = []
    for unit, count in components:
        if count > 0:
            formatted_parts.append(f"{count} {unit}{('s' if count > 1 else '')}")
    if len(formatted_parts) == 1:
        return formatted_parts[0]
    elif len(formatted_parts) == 2:
        return f'{formatted_parts[0]} and {formatted_parts[1]}'
    else:
        return ', '.join(formatted_parts[:-1]) + f' and {formatted_parts[-1]}'

def format_duration(seconds):
    if seconds == 0:
        return 'now'
    years, seconds = divmod(seconds, 365 * 24 * 3600)
    days, seconds = divmod(seconds, 24 * 3600)
    hours, seconds = divmod(seconds, 3600)
    minutes, seconds = divmod(seconds, 60)
    components = []
    if years > 0:
        components.append(f"{years} year{('s' if years > 1 else '')}")
    if days > 0:
        components.append(f"{days} day{('s' if days > 1 else '')}")
    if hours > 0:
        components.append(f"{hours} hour{('s' if hours > 1 else '')}")
    if minutes > 0:
        components.append(f"{minutes} minute{('s' if minutes > 1 else '')}")
    if seconds > 0:
        components.append(f"{seconds} second{('s' if seconds > 1 else '')}")
    return format_components(components)

